const fs = require('fs');
const baseDir = $env.TALENZA_DATA_DIR || 'C:/script/BMWHACK/talenza-data';
const candidatesDir = baseDir + '/candidates';
const indexPath = candidatesDir + '/index.json';
const legacyPath = baseDir + '/candidates.json';

const ids = $input.first().json.body.candidate_ids || [];
if (!Array.isArray(ids) || ids.length === 0) {
  return [{ json: { status: 'success', count: 0, candidates: [] } }];
}

let selected = [];

if (fs.existsSync(indexPath)) {
  let index = [];
  try {
    index = JSON.parse(fs.readFileSync(indexPath, 'utf8'));
    if (!Array.isArray(index)) index = [];
  } catch (e) {
    throw new Error('Failed to read candidates index: ' + e.message);
  }

  const byId = new Map(index.map(x => [x.candidate_id, x]));
  for (const id of ids) {
    const meta = byId.get(id);
    if (!meta) continue;
    const rel = meta.file || ('candidates/' + id + '.json');
    const fullPath = baseDir + '/' + rel;
    if (!fs.existsSync(fullPath)) continue;
    try {
      selected.push(JSON.parse(fs.readFileSync(fullPath, 'utf8')));
    } catch (e) {
      throw new Error('Failed to read candidate file for ' + id + ': ' + e.message);
    }
  }
} else if (fs.existsSync(legacyPath)) {
  let all = [];
  try {
    all = JSON.parse(fs.readFileSync(legacyPath, 'utf8'));
    if (!Array.isArray(all)) all = [];
  } catch (e) {
    throw new Error('Failed to read legacy candidates.json: ' + e.message);
  }
  selected = all.filter(c => ids.includes(c.candidate_id));
}

return [{ json: { status: 'success', count: selected.length, candidates: selected } }];

