} else if (isCrisis && internalTop >= 0.58) {
  recommended = 'internal_first';
} else if (internalTop >= scoringThresholds.internalStrong && (internalTop - externalTop) >= scoringThresholds.internalMaterialGap) {
  recommended = 'internal_first';
} else if (internalTop < scoringThresholds.internalAcceptable && (externalTop - internalTop) >= scoringThresholds.externalMaterialGap && (!hasUrgency || urgencyWeeks >= 10)) {
  recommended = 'external_first';
} else {
  recommended = 'hybrid';
}

const costTimeSignals = {
  external_search_fee_eur: externalAssumptions.searchFeeEur,
  external_time_to_fill_weeks: externalAssumptions.timeToFillWeeks,
  urgency_weeks: hasUrgency ? urgencyWeeks : null,
  urgency_vs_external_time_gap_weeks: hasUrgency ? Math.round((externalAssumptions.timeToFillWeeks - urgencyWeeks) * 10) / 10 : null
};

const wrongHireRisk = {
  scenario_type: scenarioType || null,
  crisis_mode: isCrisis,
  external_wrong_hire_impact: isCrisis ? 'catastrophic' : 'high',
  internal_wrong_hire_impact: isCrisis ? 'high' : 'medium'
};

const rationale = [];
rationale.push(`Urgency=${hasUrgency ? urgencyWeeks + 'w' : 'unknown'}; external time-to-fill=${externalAssumptions.timeToFillWeeks}w`);
rationale.push(`Pipeline strength: internal_top=${internalTop.toFixed(3)}, external_top=${externalTop.toFixed(3)}`);
rationale.push(`Pool averages: internal_avg=${internalAvg.toFixed(3)}, external_avg=${externalAvg.toFixed(3)}`);
rationale.push(`Cost delta: external search fee assumed ${externalAssumptions.searchFeeEur} EUR`);
if (isCrisis) rationale.push('Crisis scenario elevates wrong-hire impact, favoring known internal execution if viable');

return [{
  json: {
    status: 'success',
    scenario_id: scenarioId,
    recommended_strategy: recommended,
    strategy_options: ['internal_first', 'external_first', 'hybrid'],
    decision_inputs: {
      urgency_weeks: hasUrgency ? urgencyWeeks : null,
      internal_pipeline_strength: {
        candidate_count: internal.length,
        top_weighted_score: Math.round(internalTop * 10000) / 10000,
        average_weighted_score: Math.round(internalAvg * 10000) / 10000
      },
      external_pipeline_strength: {
        candidate_count: external.length,
        top_weighted_score: Math.round(externalTop * 10000) / 10000,
        average_weighted_score: Math.round(externalAvg * 10000) / 10000
      },
      cost_time_signals: costTimeSignals,
      wrong_hire_risk: wrongHireRisk
    },
    top_internal: internal.slice(0, 3),
    top_external: external.slice(0, 3),
    thresholds_used: scoringThresholds,
    rationale
  }
}];
